VALUES
  ('68b876ffbb18ee74c974eed8', '0001/2025', 2025, 'senappen_retencao', NULL, 'Breno Cartaxo', 'Base de CÃ¡lculo IRRF - RetenÃ§Ã£o nas NFâs 993 e 1023', '<p class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;">OFÃCIO NÂº 134/2025 - DIRETORIA GPS/PF-SENAPPEN</strong></p><p class="ql-align-right"><strong style="color: rgb(0, 0, 0); background-color: transparent;">BrasÃ­lia/DF, 02 de setembro de 2025</strong></p><p class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Ã SECRETARIA NACIONAL DE POLÃTICAS PENAIS - SENAPPEN</strong></p><p class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;">A/C Breno Cartaxo</strong></p><p class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;">ASSUNTO:</strong><span style="color: rgb(0, 0, 0); background-color: transparent;">&nbsp;Base de CÃ¡lculo IRRF - RetenÃ§Ã£o nas NFâs 993 e 1023</span></p><p class="ql-align-justify"><span style="color: rgb(0, 0, 0); background-color: transparent;">Prezado Fiscal,</span></p><p class="ql-align-justify"><span style="color: rgb(0, 0, 0); background-color: transparent;">A </span><strong style="color: rgb(0, 0, 0); background-color: transparent;">GPS FACILITY E CONSTRUÃÃO LTDA.</strong><span style="color: rgb(0, 0, 0); background-color: transparent;">, pessoa jurÃ­dica de direito privado, inscrita no CNPJ sob o nÂº 14.842.018/0001-45, neste ato representada por seu Diretor Executivo vem, respeitosamente, perante Vossa Senhoria, apresentar sua fundamentaÃ§Ã£o tÃ©cnica e jurÃ­dica para a revisÃ£o da alÃ­quota de retenÃ§Ã£o do Imposto de Renda Pessoa JurÃ­dica (IRPJ) aplicada sobre as notas fiscais em epÃ­grafe, no Ã¢mbito do </span><strong style="color: rgb(0, 0, 0); background-color: transparent;">Contrato nÂº 01/2025</strong><span style="color: rgb(0, 0, 0); background-color: transparent;">.</span></p><p class="ql-align-justify"><br></p><p class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;">SÃNTESE DO CASO</strong></p><p class="ql-align-justify"><span style="background-color: transparent;">Esta Contratada foi notificada sobre a aplicaÃ§Ã£o da alÃ­quota de </span><strong style="background-color: transparent;">4,80%</strong><span style="background-color: transparent;"> para a retenÃ§Ã£o de IRPJ sobre as faturas referentes Ã  prestaÃ§Ã£o dos serviÃ§os de copeiragem e garÃ§om. A fiscalizaÃ§Ã£o justificou a manutenÃ§Ã£o desta alÃ­quota com base na SoluÃ§Ã£o de Consulta (SC) nÂº 55-COSIT, de 2013.</span></p><p class="ql-align-justify"><span style="background-color: transparent;">Contudo, reiteramos nosso entendimento de que a alÃ­quota correta Ã© de </span><strong style="background-color: transparent;">1,20%</strong><span style="background-color: transparent;">, conforme a legislaÃ§Ã£o que rege a matÃ©ria, uma vez que o objeto contratual Ã© </span><strong style="background-color: transparent;">executado com o fornecimento integral de materiais e equipamentos</strong><span style="background-color: transparent;">, condiÃ§Ã£o que se enquadra na previsÃ£o da InstruÃ§Ã£o Normativa (IN) RFB nÂº 1.234, de 2012.</span></p><p class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;">DA FUNDAMENTAÃÃO JURÃDICA E CONTRATUAL</strong></p><p class="ql-align-justify"><span style="background-color: transparent;">A aplicaÃ§Ã£o da SC nÂº 55-COSIT/2013 ao presente caso Ã© equivocada, conforme demonstramos a seguir, com base na legislaÃ§Ã£o tributÃ¡ria aplicÃ¡vel e nos prÃ³prios termos do contrato firmado entre as partes.</span></p><p class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;">DA INAPLICABILIDADE DA SOLUÃÃO DE CONSULTA COSIT NÂº 55/2013</strong></p><p class="ql-align-justify"><span style="background-color: transparent;">A referida SoluÃ§Ã£o de Consulta trata, especificamente, da apuraÃ§Ã£o da </span><strong style="background-color: transparent;">base de cÃ¡lculo do IRPJ e da CSLL para empresas tributadas sob o regime do Lucro Presumido</strong><span style="background-color: transparent;">. Ela define os percentuais de presunÃ§Ã£o (8% ou 32%) a serem aplicados sobre a receita bruta para se encontrar o lucro presumido, que Ã© a base sobre a qual o imposto devido pela </span><em style="background-color: transparent;">empresa contribuinte</em><span style="background-color: transparent;"> serÃ¡ calculado.</span></p><p class="ql-align-justify"><span style="background-color: transparent;">O tema em discussÃ£o aqui, entretanto, nÃ£o Ã© a apuraÃ§Ã£o interna de tributos pela Contratada, mas sim a </span><strong style="background-color: transparent;">retenÃ§Ã£o na fonte (IRRF)</strong><span style="background-color: transparent;">, que Ã© uma obrigaÃ§Ã£o do </span><em style="background-color: transparent;">tomador do serviÃ§o</em><span style="background-color: transparent;"> (Contratante) e regulada por norma especÃ­fica. A SC nÂº 55/2013 nÃ£o estabelece alÃ­quotas de retenÃ§Ã£o para pagamentos efetuados pela AdministraÃ§Ã£o PÃºblica.</span></p><p class="ql-align-justify"><span style="background-color: transparent;">Adicionalmente, cumpre esclarecer que o regime tributÃ¡rio desta Contratada, isto Ã© a GPS FACILITY E CONSTRUÃÃO LTDA. Ã© o </span><strong style="background-color: transparent;">Lucro Real</strong><span style="background-color: transparent;">, tornando a lÃ³gica da presunÃ§Ã£o de lucro, central Ã  SC nÂº 55/2013, inaplicÃ¡vel Ã  nossa realidade fiscal.</span></p><p class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;">DO ENQUADRAMENTO NA IN RFB NÂº 1.234/2012 E SEU ANEXO I</strong></p><p class="ql-align-justify"><span style="background-color: transparent;">A norma que rege a retenÃ§Ã£o de tributos federais nos pagamentos efetuados por Ã³rgÃ£os da administraÃ§Ã£o pÃºblica, como a SENAPPEN, Ã© a </span><strong style="background-color: transparent;">InstruÃ§Ã£o Normativa RFB nÂº 1.234, de 2012</strong><span style="background-color: transparent;">, em seu </span><strong style="background-color: transparent;">Anexo I (Tabela de RetenÃ§Ã£o)</strong><span style="background-color: transparent;"> Ã© claro ao diferenciar as alÃ­quotas: </span></p><blockquote class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;">7.1 - CÃ³digo 6190 (9,45% total / 4,80% IRPJ):</strong><span style="color: rgb(0, 0, 0); background-color: transparent;"> AplicÃ¡vel a serviÃ§os de "Limpeza", "LocaÃ§Ã£o de mÃ£o de obra" e "Demais serviÃ§os".</span></blockquote><blockquote class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;">7.2 - CÃ³digo 6147 (5,85% total / 1,20% IRPJ):</strong><span style="color: rgb(0, 0, 0); background-color: transparent;"> AplicÃ¡vel a ""ServiÃ§os prestados com emprego de materiais""</span></blockquote><p class="ql-align-justify"><span style="background-color: transparent;">A prÃ³pria instruÃ§Ã£o normativa, em seu Art. 2Âº, Â§ 7Âº, inciso I, define o que sÃ£o "serviÃ§os prestados com emprego de materiais":</span></p><blockquote class="ql-align-justify"><em style="color: rgb(0, 0, 0); background-color: transparent;">"[...] os serviÃ§os cuja prestaÃ§Ã£o envolva o</em></blockquote><blockquote class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;"><em>fornecimento pelo contratado de materiais, desde que tais materiais estejam discriminados no contrato ou em planilhas Ã  parte integrante do contrato</em></strong><em style="color: rgb(0, 0, 0); background-color: transparent;">, e na nota fiscal ou fatura de prestaÃ§Ã£o de serviÃ§os;"</em></blockquote><p class="ql-align-justify"><span style="background-color: transparent;">O Contrato nÂº 01/2025 atende plenamente a estes requisitos. A obrigaÃ§Ã£o de fornecer materiais e equipamentos Ã© condiÃ§Ã£o essencial da contrataÃ§Ã£o, prevista desde sua origem:</span></p><blockquote>Estudo TÃ©cnico Preliminar (ETP): O ETP nÂº 63/2024, que fundamentou a licitaÃ§Ã£o, detalha uma extensa lista de materiais e equipamentos a serem fornecidos pela Contratada para a SENAPPEN (Grupo VI), incluindo itens como mÃ¡quinas de cafÃ© industrial, carrinhos de aÃ§o inox, bebedouros, jarras, xÃ­caras, louÃ§as, alÃ©m de todos os insumos de consumo.</blockquote><blockquote>VinculaÃ§Ã£o Contratual: A ClÃ¡usula Primeira do Contrato, em seu item 1.3, vincula expressamente o Estudo TÃ©cnico Preliminar e a Planilha de Custos como partes integrantes do ajuste, formalizando a obrigaÃ§Ã£o de fornecimento.</blockquote><p class="ql-align-justify"><span style="background-color: transparent;">Fica claro, portanto, que a natureza do serviÃ§o nÃ£o Ã© de mera locaÃ§Ã£o de mÃ£o de obra, mas sim uma prestaÃ§Ã£o de serviÃ§o com </span><strong style="background-color: transparent;">emprego indispensÃ¡vel e contratualmente previsto de materiais e equipamentos</strong><span style="background-color: transparent;">.</span></p><p class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;">DA CONFIRMAÃÃO PELA SOLUÃÃO DE CONSULTA COSIT NÂº 269/2024</strong></p><p class="ql-align-justify"><span style="background-color: transparent;">Para dirimir quaisquer dÃºvidas remanescentes, a Receita Federal do Brasil publicou a </span><strong style="background-color: transparent;">SoluÃ§Ã£o de Consulta COSIT nÂº 269, de 27 de setembro de 2024</strong><span style="background-color: transparent;">, que trata exatamente desta matÃ©ria. Este novo entendimento, vinculante para a AdministraÃ§Ã£o TributÃ¡ria, esclarece de forma definitiva que:</span></p><blockquote class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;">11.1 - Equipamentos sÃ£o considerados Materiais para fins de RetenÃ§Ã£o:</strong><span style="color: rgb(0, 0, 0); background-color: transparent;"> "A prestaÃ§Ã£o de serviÃ§os de limpeza </span><strong style="color: rgb(0, 0, 0); background-color: transparent;">somente com o emprego de equipamentos</strong><span style="color: rgb(0, 0, 0); background-color: transparent;"> que sejam imprescindÃ­veis Ã  execuÃ§Ã£o de tais serviÃ§os </span><strong style="color: rgb(0, 0, 0); background-color: transparent;">Ã© considerada ''prestaÃ§Ã£o de serviÃ§os com emprego de materiais''</strong><span style="color: rgb(0, 0, 0); background-color: transparent;">, conforme previsÃ£o do Â§ 7Âº, inciso I, do art. 2Âº da InstruÃ§Ã£o Normativa RFB nÂº 1.234, de 2012."</span></blockquote><blockquote class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;">11.2 - DistinÃ§Ã£o entre RetenÃ§Ã£o e Base de CÃ¡lculo (Lucro Presumido):</strong><span style="color: rgb(0, 0, 0); background-color: transparent;"> A SC nÂº 269/2024 Ã© categÃ³rica ao afirmar que a legislaÃ§Ã£o sobre a base de cÃ¡lculo do lucro presumido </span><strong style="color: rgb(0, 0, 0); background-color: transparent;">nÃ£o se confunde</strong><span style="color: rgb(0, 0, 0); background-color: transparent;"> com as regras de retenÃ§Ã£o na fonte. Ela cita o Art. 38, II, da prÃ³pria IN 1234/2012 para reforÃ§ar que as regras da instruÃ§Ã£o normativa "nÃ£o alteram a aplicaÃ§Ã£o dos percentuais de presunÃ§Ã£o para efeito de apuraÃ§Ã£o da base de cÃ¡lculo do IR".</span></blockquote><p class="ql-align-justify"><span style="background-color: transparent;">Esta recente SoluÃ§Ã£o de Consulta nÃ£o apenas valida nosso argumento, mas utiliza a prÃ³pria SC nÂº 55/2013 para demonstrar que ela se aplica a um contexto tributÃ¡rio distinto (cÃ¡lculo do imposto no Lucro Presumido) e </span><strong style="background-color: transparent;">nÃ£o deve ser usada para definir a alÃ­quota de retenÃ§Ã£o na fonte</strong><span style="background-color: transparent;">, que Ã© o caso em tela.</span></p><p class="ql-align-justify"><strong style="color: rgb(0, 0, 0); background-color: transparent;">CONCLUSÃO E PEDIDO</strong></p><p class="ql-align-justify"><span style="background-color: transparent;">Diante do exposto, resta demonstrado que:&nbsp;</span></p><p class="ql-align-justify"><span style="color: rgb(0, 0, 0); background-color: transparent;">a) A SC COSIT nÂº 55/2013 Ã© inaplicÃ¡vel ao caso, por tratar de base de cÃ¡lculo de um regime tributÃ¡rio especÃ­fico (Lucro Presumido) e nÃ£o de retenÃ§Ã£o na fonte pela AdministraÃ§Ã£o PÃºblica.&nbsp;</span></p><p class="ql-align-justify"><span style="color: rgb(0, 0, 0); background-color: transparent;">b) A norma aplicÃ¡vel Ã© a IN RFB nÂº 1.234/2012, que prevÃª a alÃ­quota de IRPJ de </span><strong style="color: rgb(0, 0, 0); background-color: transparent;">1,20%</strong><span style="color: rgb(0, 0, 0); background-color: transparent;"> para serviÃ§os com emprego de materiais (CÃ³digo 6147).&nbsp;</span></p><p class="ql-align-justify"><span style="color: rgb(0, 0, 0); background-color: transparent;">c) O Contrato nÂº 01/2025, conforme seu texto e anexos (ETP e Planilha de Custos), exige o fornecimento de vastos materiais e equipamentos, enquadrando-se na hipÃ³tese da alÃ­quota reduzida.&nbsp;</span></p><p class="ql-align-justify"><span style="color: rgb(0, 0, 0); background-color: transparent;">d) A recente SC COSIT nÂº 269/2024 confirma que equipamentos essenciais sÃ£o considerados materiais para fins de retenÃ§Ã£o, pacificando o entendimento em favor da alÃ­quota de 1,20%.</span></p><p class="ql-align-justify"><span style="background-color: transparent;">Pelo exposto, solicitamos a Vossa Senhoria a reanÃ¡lise do pleito, para que seja aplicada a alÃ­quota de </span><strong style="background-color: transparent;">1,20%</strong><span style="background-color: transparent;"> para a retenÃ§Ã£o de IRPJ, procedendo-se com a retificaÃ§Ã£o dos valores retidos a maior nas Notas Fiscais nÂº 993 e 1023 e adotando-se este percentual para os pagamentos futuros no Ã¢mbito do Contrato nÂº 01/2025, informamos tambÃ©m que as prÃ³ximas NFâs virÃ£o discriminadas com os valores Ã  tÃ­tulo de materiais, insumos e equipamentos.</span></p><p class="ql-align-center"><span style="color: rgb(0, 0, 0); background-color: transparent;">Certos de vossa compreensÃ£o, colocamo-nos Ã  disposiÃ§Ã£o para quaisquer esclarecimentos adicionais.</span></p><p class="ql-align-center"><span style="color: rgb(0, 0, 0); background-color: transparent;">Respeitosamente,</span></p>', '2025-09-02', 'rascunho', 'SAULLO JOSÃ DE SOUZA ALVES', 'Analista de Contratos e LicitaÃ§Ãµes', '14842018000145', 'aprovado', 'saullo.souza@gpsfacility.com', '2025-09-03T17:22:14.813Z'::timestamptz, NULL, false, '6890c76710ea9fe150b51c65', 'saullo.souza@gpsfacility.com', '2025-09-03T17:12:31.262000'::timestamptz, '2025-09-03T17:32:15.275000'::timestamptz)
ON CONFLICT (id) DO NOTHING;

